[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "workshop-itinerary-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "workshop-itinerary-surface",
      "value": {
        "schedule": [
          {
            "startTime": "08:30",
            "endTime": "09:00",
            "title": "Registration & Welcome Coffee",
            "description": "Networking and check-in.",
            "icon": "/icons/coffee.png"
          },
          {
            "startTime": "09:00",
            "endTime": "09:15",
            "title": "Opening Remarks",
            "description": "Welcome and workshop overview.",
            "icon": "/icons/megaphone.png"
          },
          {
            "startTime": "09:15",
            "endTime": "10:30",
            "title": "Keynote: The Future of Leadership",
            "description": "By a guest industry expert.",
            "icon": "/icons/megaphone.png"
          },
          {
            "startTime": "10:30",
            "endTime": "10:45",
            "title": "Morning Break",
            "description": "Coffee and refreshments.",
            "icon": "/icons/coffee.png"
          },
          {
            "startTime": "10:45",
            "endTime": "12:00",
            "title": "Breakout Session 1: Strategic Decision Making",
            "description": "Interactive session on critical thinking.",
            "icon": "/icons/group.png"
          },
          {
            "startTime": "12:00",
            "endTime": "13:00",
            "title": "Lunch",
            "description": "Networking lunch.",
            "icon": "/icons/food.png"
          },
          {
            "startTime": "13:00",
            "endTime": "14:15",
            "title": "Breakout Session 2: Leading High-Performance Teams",
            "description": "Techniques for team motivation and management.",
            "icon": "/icons/group.png"
          },
          {
            "startTime": "14:15",
            "endTime": "14:30",
            "title": "Afternoon Break",
            "description": "Refreshments.",
            "icon": "/icons/coffee.png"
          },
          {
            "startTime": "14:30",
            "endTime": "15:45",
            "title": "Breakout Session 3: Change Management",
            "description": "Navigating organizational change effectively.",
            "icon": "/icons/group.png"
          },
          {
            "startTime": "15:45",
            "endTime": "16:45",
            "title": "Interactive Leadership Challenge",
            "description": "Practical application of workshop concepts in a team-based simulation.",
            "icon": "/icons/challenge.png"
          },
          {
            "startTime": "16:45",
            "endTime": "17:00",
            "title": "Closing Remarks & Wrap-up",
            "description": "Summary of key takeaways and next steps.",
            "icon": "/icons/megaphone.png"
          }
        ],
        "assumptions": [
          "All attendees participate in all three breakout sessions sequentially.",
          "Specific content for each session is illustrative and can be customized by the organizers.",
          "Breaks are 15 minutes to allow for participant refreshment and room transitions.",
          "An \"Interactive Leadership Challenge\" session is included to provide practical application and enhance engagement.",
          "Room assignments are optimized for the flow of a single cohort through the workshop."
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "workshop-itinerary-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium"
          },
          "children": [
            {
              "id": "header_card",
              "type": "Card",
              "children": [
                {
                  "id": "header_column",
                  "type": "Column",
                  "properties": {
                    "spacing": "medium"
                  },
                  "children": [
                    {
                      "id": "main_title",
                      "type": "Text",
                      "properties": {
                        "text": "Corporate Leadership Workshop Itinerary",
                        "style": "heading",
                        "horizontalAlignment": "center"
                      }
                    },
                    {
                      "id": "details_row",
                      "type": "Row",
                      "properties": {
                        "distribution": "spaceAround"
                      },
                      "children": [
                        {
                          "id": "date_col",
                          "type": "Column",
                          "properties": {
                            "horizontalAlignment": "center"
                          },
                          "children": [
                            {
                              "id": "date_label",
                              "type": "Text",
                              "properties": {
                                "text": "Date",
                                "style": "label"
                              }
                            },
                            {
                              "id": "date_value",
                              "type": "Text",
                              "properties": {
                                "text": "2024-11-15"
                              }
                            }
                          ]
                        },
                        {
                          "id": "location_col",
                          "type": "Column",
                          "properties": {
                            "horizontalAlignment": "center"
                          },
                          "children": [
                            {
                              "id": "location_label",
                              "type": "Text",
                              "properties": {
                                "text": "Location",
                                "style": "label"
                              }
                            },
                            {
                              "id": "location_value",
                              "type": "Text",
                              "properties": {
                                "text": "Chicago, USA"
                              }
                            }
                          ]
                        },
                        {
                          "id": "time_col",
                          "type": "Column",
                          "properties": {
                            "horizontalAlignment": "center"
                          },
                          "children": [
                            {
                              "id": "time_label",
                              "type": "Text",
                              "properties": {
                                "text": "Time",
                                "style": "label"
                              }
                            },
                            {
                              "id": "time_value",
                              "type": "Text",
                              "properties": {
                                "text": "08:30 - 17:00"
                              }
                            }
                          ]
                        }
                      ]
                    }
                  ]
                }
              ]
            },
            {
              "id": "schedule_list",
              "type": "List",
              "properties": {
                "binding": {
                  "dataModelKey": "schedule"
                }
              },
              "children": [
                {
                  "id": "schedule_item_template",
                  "type": "Row",
                  "properties": {
                    "spacing": "medium",
                    "verticalAlignment": "center"
                  },
                  "children": [
                    {
                      "id": "item_time_col",
                      "type": "Column",
                      "properties": {
                        "width": "60px",
                        "horizontalAlignment": "center"
                      },
                      "children": [
                        {
                          "id": "item_icon",
                          "type": "Image",
                          "properties": {
                            "source": "/icons/clock.png",
                            "width": "24px",
                            "height": "24px"
                          }
                        },
                        {
                          "id": "item_start_time",
                          "type": "Text",
                          "properties": {
                            "text": {
                              "binding": "item.startTime"
                            },
                            "style": "caption"
                          }
                        }
                      ]
                    },
                    {
                      "id": "item_icon_col",
                      "type": "Column",
                      "properties": {
                        "width": "40px",
                        "horizontalAlignment": "center"
                      },
                      "children": [
                        {
                          "id": "item_type_icon",
                          "type": "Image",
                          "properties": {
                            "source": {
                              "binding": "item.icon"
                            },
                            "width": "32px",
                            "height": "32px"
                          }
                        }
                      ]
                    },
                    {
                      "id": "item_details_col",
                      "type": "Column",
                      "children": [
                        {
                          "id": "item_title",
                          "type": "Text",
                          "properties": {
                            "text": {
                              "binding": "item.title"
                            },
                            "weight": "bold"
                          }
                        },
                        {
                          "id": "item_description",
                          "type": "Text",
                          "properties": {
                            "text": {
                              "binding": "item.description"
                            },
                            "style": "caption"
                          }
                        }
                      ]
                    }
                  ]
                }
              ]
            },
            {
              "id": "assumptions_card",
              "type": "Card",
              "children": [
                {
                  "id": "assumptions_column",
                  "type": "Column",
                  "properties": {
                    "spacing": "small"
                  },
                  "children": [
                    {
                      "id": "assumptions_title",
                      "type": "Text",
                      "properties": {
                        "text": "Assumptions",
                        "style": "subheading"
                      }
                    },
                    {
                      "id": "assumptions_list",
                      "type": "List",
                      "properties": {
                        "binding": {
                          "dataModelKey": "assumptions"
                        }
                      },
                      "children": [
                        {
                          "id": "assumption_item_template",
                          "type": "Row",
                          "properties": {
                            "spacing": "small"
                          },
                          "children": [
                            {
                              "id": "bullet_point",
                              "type": "Text",
                              "properties": {
                                "text": "•"
                              }
                            },
                            {
                              "id": "assumption_text",
                              "type": "Text",
                              "properties": {
                                "text": {
                                  "binding": "item"
                                }
                              }
                            }
                          ]
                        }
                      ]
                    }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
